<script setup lang="ts">
// Export files generated by the current account (kept 7 days), with details
// and re-download.
import { ref } from 'vue';
import Dialog from '../../../components/ui/Dialog.vue';
import DataTable from '../../../components/ui/DataTable.vue';
import DetailList from '../../../components/ui/DetailList.vue';
import Notice from '../../../components/ui/Notice.vue';
import Pagination from '../../../components/ui/Pagination.vue';
import StatusBadge from '../../../components/ui/StatusBadge.vue';
import { useApiData } from '../../../composables/useApiData';
import { t } from '../../../lib/i18n';
import { formatDateTime } from '../../../lib/money';
import { downloadExport, exportContent, exportStateLabel, EXPORTS_ENDPOINT, type ExportJob } from './dailyExports';
import type { Page } from './ledger';

const emit = defineEmits<{ close: [] }>();

const page = ref(1);
const size = ref(10);
const history = useApiData<Page<ExportJob>>(() => `${EXPORTS_ENDPOINT}?page=${page.value}&size=10`);
const busy = ref(false);
const error = ref('');
const selected = ref<ExportJob | null>(null);

const columns = [
  { key: 'content', label: t('导出内容') },
  { key: 'time', label: t('生成时间'), nowrap: true },
  { key: 'state', label: t('状态') },
  { key: 'actions', label: t('操作'), align: 'right' as const },
];
const badgeState = (state: string) => ({ COMPLETED: 'SUCCESS', FAILED: 'FAILURE', CANCELLED: 'CANCELLED', EXPIRED: 'WITHDRAWN' }[state] || 'WITHDRAWN');

function close() { if (!busy.value) emit('close'); }

async function download(job: ExportJob) {
  if (busy.value) return;
  busy.value = true;
  error.value = '';
  try {
    await downloadExport(job);
  } catch (reason) {
    error.value = (reason as Error).message;
  } finally {
    busy.value = false;
  }
}

const range = (job: ExportJob) => `${job.filter?.from || t('不限')} — ${job.filter?.to || t('不限')}`;
</script>

<template>
  <Dialog drawer :title="t('导出记录')" :subtitle="t('仅显示当前账号生成的文件，保留 7 天。')" @close="close">
    <div class="body">
      <Notice v-if="error" tone="danger">{{ error }}</Notice>
      <div class="table">
        <DataTable :columns="columns" :rows="history.data.value?.items" :row-key="(job: ExportJob) => job.id" :loading="history.loading.value"
          :error="history.error.value" :label="t('导出记录')" @retry="history.reload()">
          <template #cell-content="{ row }">{{ exportContent(row) }}</template>
          <template #cell-time="{ row }">{{ formatDateTime(row.completedAt || row.createdAt) }}</template>
          <template #cell-state="{ row }"><StatusBadge :state="badgeState(row.state)" :label="exportStateLabel(row.state)" /></template>
          <template #cell-actions="{ row }">
            <div class="actions">
              <button type="button" class="ld-link" :disabled="busy" @click="selected = row">{{ t('查看') }}</button>
              <button v-if="row.state === 'COMPLETED'" type="button" class="ld-link primary" :disabled="busy" @click="download(row)">{{ t('下载') }}</button>
            </div>
          </template>
        </DataTable>
        <Pagination v-model:page="page" v-model:size="size" :sizes="[10]" :total="history.data.value?.total ?? 0" :loading="history.loading.value" />
      </div>
    </div>
  </Dialog>
  <Dialog v-if="selected" :title="t('导出详情')" @close="selected = null">
    <DetailList :items="[
      [t('导出内容'), exportContent(selected)],
      [t('日期范围'), range(selected)],
      [t('状态'), exportStateLabel(selected.state)],
      [t('数据时点'), formatDateTime(selected.snapshotAt)],
      [t('行数'), selected.resultCount == null ? '—' : String(selected.resultCount)],
      [t('有效至'), formatDateTime(selected.expiresAt)],
    ]" />
  </Dialog>
</template>

<style scoped>
.body { display: grid; gap: 14px; }
.table { border: 1px solid var(--hs-border); border-radius: 12px; overflow: hidden; }
.actions { display: inline-flex; gap: 12px; }
.ld-link { min-height: 0; padding: 0; color: var(--hs-text-3); background: none; border: 0; font: inherit; font-size: var(--hs-text-xs); cursor: pointer; }
.ld-link.primary { color: var(--hs-accent); }
.ld-link:hover:not(:disabled) { text-decoration: underline; text-underline-offset: 3px; }
.ld-link:disabled { opacity: .5; cursor: not-allowed; }
</style>
